package autonewsroller.visuals;

import autonewsroller.model.VisualPlan;import java.awt.*;import java.awt.image.BufferedImage;import java.nio.file.*;import javax.imageio.ImageIO;
public final class CardRenderer {public Path render(VisualPlan.Item item,Path out,int w,int h)throws Exception{Files.createDirectories(out.getParent());BufferedImage img=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);Graphics2D g=img.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(18,20,24));g.fillRect(0,0,w,h);g.setColor(new Color(42,48,58));g.fillRoundRect(64,100,w-128,h-200,42,42);g.setColor(Color.WHITE);drawWrapped(g,item.title(),new Font("SansSerif",Font.BOLD,58),92,210,w-184,76);g.setColor(new Color(220,224,230));drawWrapped(g,item.body(),new Font("SansSerif",Font.PLAIN,38),92,520,w-184,52);g.setColor(new Color(160,170,185));g.setFont(new Font("SansSerif",Font.BOLD,26));g.drawString("AutoNewsRoller • "+item.type(),92,h-130);g.dispose();ImageIO.write(img,"png",out.toFile());return out;}private static void drawWrapped(Graphics2D g,String text,Font font,int x,int y,int max,int step){g.setFont(font);FontMetrics fm=g.getFontMetrics();String[] words=(text==null?"":text).split("\\s+");StringBuilder line=new StringBuilder();int yy=y;for(String word:words){String test=line.isEmpty()?word:line+" "+word;if(fm.stringWidth(test)>max&&!line.isEmpty()){g.drawString(line.toString(),x,yy);yy+=step;line=new StringBuilder(word);}else{if(!line.isEmpty())line.append(' ');line.append(word);}}if(!line.isEmpty())g.drawString(line.toString(),x,yy);}}
